/** A project's budget. The source writes every figure; `remaining` may be negative. */
export type ProjectSourceBudget = {
  unit: "hours" | "money";
  consumed: number;
  status?: "unknown" | "ok" | "warning" | "over" | undefined;
  total?: number | undefined;
  remaining?: number | undefined;
  since?: string | undefined;
};

/** What `syncTimeEntries` receives: the window to list, as local dates in the
user's time zone, and at most 20 changes to apply first, in order. */
export type TimeSyncRequest = {
  changes: (
    | {
        values: {
          localDate: string;
          minutes: number;
          running: boolean;
          projectRemoteId: string;
          taskName: string;
          countingSince?: string | undefined;
          taskRemoteId?: string | undefined;
        };
        kind: "upsert";
        syncKey: string;
        remoteId?: string | undefined;
        agreed?:
          | {
              localDate: string;
              minutes: number;
              running: boolean;
              projectRemoteId: string;
              taskName: string;
              countingSince?: string | undefined;
              taskRemoteId?: string | undefined;
            }
          | undefined;
      }
    | {
        kind: "delete";
        syncKey: string;
        remoteId?: string | undefined;
        agreed?:
          | {
              localDate: string;
              minutes: number;
              running: boolean;
              projectRemoteId: string;
              taskName: string;
              countingSince?: string | undefined;
              taskRemoteId?: string | undefined;
            }
          | undefined;
      }
  )[];
  timeZone: string;
  from: string;
  to: string;
};

/** One change: an entry to create or update, or one to delete. Send its
`syncKey` as your client reference, so a retry never duplicates. `agreed`
holds the values both sides last agreed on, when there are some. */
export type TimeSyncChange =
  | {
      values: {
        localDate: string;
        minutes: number;
        running: boolean;
        projectRemoteId: string;
        taskName: string;
        countingSince?: string | undefined;
        taskRemoteId?: string | undefined;
      };
      kind: "upsert";
      syncKey: string;
      remoteId?: string | undefined;
      agreed?:
        | {
            localDate: string;
            minutes: number;
            running: boolean;
            projectRemoteId: string;
            taskName: string;
            countingSince?: string | undefined;
            taskRemoteId?: string | undefined;
          }
        | undefined;
    }
  | {
      kind: "delete";
      syncKey: string;
      remoteId?: string | undefined;
      agreed?:
        | {
            localDate: string;
            minutes: number;
            running: boolean;
            projectRemoteId: string;
            taskName: string;
            countingSince?: string | undefined;
            taskRemoteId?: string | undefined;
          }
        | undefined;
    };

/** An entry's values: its day, whole minutes, whether it runs and since when
its count started, its project and its task. Never a note. */
export type TimeSyncEntryValues = {
  localDate: string;
  minutes: number;
  running: boolean;
  projectRemoteId: string;
  taskName: string;
  countingSince?: string | undefined;
  taskRemoteId?: string | undefined;
};

/** What `syncTimeEntries` answers: one result per change, and the remote entries in the window. */
export type TimeSyncResult = {
  entries: {
    remoteId: string;
    updatedAt: string;
    localDate: string;
    minutes: number;
    running: boolean;
    projectRemoteId: string;
    taskName: string;
    countingSince?: string | undefined;
    taskRemoteId?: string | undefined;
    clientRef?: string | undefined;
  }[];
  results: (
    | {
        status: "synced";
        syncKey: string;
        entry?:
          | {
              remoteId: string;
              updatedAt: string;
              localDate: string;
              minutes: number;
              running: boolean;
              projectRemoteId: string;
              taskName: string;
              countingSince?: string | undefined;
              taskRemoteId?: string | undefined;
              clientRef?: string | undefined;
            }
          | undefined;
      }
    | { status: "refused"; message: string; syncKey: string }
    | { status: "failed"; message: string; syncKey: string }
  )[];
};

/** How one change went: `synced` with the entry as stored (none for a
delete), `refused` for good with a sentence the user reads, or `failed`
with a sentence, to retry next round. */
export type TimeSyncChangeResult =
  | {
      status: "synced";
      syncKey: string;
      entry?:
        | {
            remoteId: string;
            updatedAt: string;
            localDate: string;
            minutes: number;
            running: boolean;
            projectRemoteId: string;
            taskName: string;
            countingSince?: string | undefined;
            taskRemoteId?: string | undefined;
            clientRef?: string | undefined;
          }
        | undefined;
    }
  | { status: "refused"; message: string; syncKey: string }
  | { status: "failed"; message: string; syncKey: string };

/** An entry as your system stores it, with `clientRef` when Ajour created it. */
export type TimeSyncRemoteEntry = {
  remoteId: string;
  updatedAt: string;
  localDate: string;
  minutes: number;
  running: boolean;
  projectRemoteId: string;
  taskName: string;
  countingSince?: string | undefined;
  taskRemoteId?: string | undefined;
  clientRef?: string | undefined;
};
